#include "master_registration.hpp"
#include <chrono>
namespace zkgpt::r7::masterB {
namespace {using Clock=std::chrono::steady_clock;double seconds(Clock::time_point t){return std::chrono::duration<double>(Clock::now()-t).count();}}
std::size_t activeColumns(const Spec&s,std::size_t row){validate(s);need(row<s.rows,"B1 row range");return row>=s.actual?0:std::min<std::size_t>(s.columns,1+(s.actual-1-row)/s.rows);}
Bytes chunkHeader(IO&io,const Master&m,std::size_t start,std::size_t count,const std::string&role,const std::string&root){need(count>0 && count<=chunkRows && start<m.spec.rows && count<=m.spec.rows-start,"B1 chunk bounds");Writer w;w.text(registrationSuite);w.text(master3::suite);w.text(root);w.text(m.spec.layout);w.text(m.spec.generators);w.text(role);w.text(io.session());auto parent=io.prefix();w.raw(Bytes(parent.begin(),parent.end()));w.number(start/chunkRows);w.number(start);w.number(count);w.number(m.spec.rows);for(std::size_t i=start;i<start+count;++i){w.number(activeColumns(m.spec,i));w.point(m.rows[i]);}return w.b;}
void checkChunk(IO&io,const Master&m,const Secret*secret,std::size_t start,std::size_t count,const std::string&role,RegistrationMetrics&stats,std::set<std::string>&seen,const std::string&root,const std::string&attack){
 auto label="B1/register/"+role+"/chunk/"+std::to_string(start/chunkRows);bindPublic(io,label+"/header",chunkHeader(io,m,start,count,role,root));auto g=hyrax_a3::generators(1024);if(io.prover() && attack=="generator-set")std::swap(g[0],g[1]);std::vector<std::vector<Fr>>d;std::vector<Fr>rho;Writer first;auto t=Clock::now();
 if(io.prover()){need(secret && secret->blinds.size()==m.spec.rows,"B1 private registration shape");for(std::size_t i=0;i<count;++i){auto active=activeColumns(m.spec,start+i);need(active>0,"B1 zero-logical row unsupported");OSRandom rng;std::vector<Fr>v;for(std::size_t j=0;j<active;++j)v.push_back(rng.scalar());auto blind=rng.scalar();if(attack=="mask-reuse" && i==1){need(d.front().size()==active,"B1 reuse test domain");v=d.front();blind=rho.front();}d.push_back(std::move(v));rho.push_back(blind);first.point(masterMSM({g.begin(),g.begin()+active},d.back())+parameters(1).hiding*blind);}}
 stats.mask_seconds+=seconds(t);auto bytes=io.message(label+"/masks",first.b);Reader mr{bytes};std::vector<G1>masks;for(std::size_t i=0;i<count;++i){auto p=mr.point();auto key=hex(r1::hash(r1::encode(p)));if(!io.prover())need(seen.insert(key).second,"B1 reused public row mask");masks.push_back(p);}mr.end();auto c=io.coin(label+"/challenge");need(!c.isZero(),"B1 zero registration challenge");Writer response;t=Clock::now();
 if(io.prover())for(std::size_t i=0;i<count;++i){auto row=start+i;for(std::size_t j=0;j<d[i].size();++j)response.scalar(d[i][j]+c*secret->value(row+m.spec.rows*j));response.scalar(rho[i]+c*secret->blinds[row]);}
 bytes=io.message(label+"/responses",response.b);stats.response_seconds+=seconds(t);stats.response_payload_bytes+=bytes.size();Reader rr{bytes};t=Clock::now();for(std::size_t i=0;i<count;++i){auto row=start+i,active=activeColumns(m.spec,row);std::vector<Fr>z;for(std::size_t j=0;j<active;++j)z.push_back(rr.scalar());auto blind=rr.scalar();if(!io.prover())need(masterMSM({g.begin(),g.begin()+active},z)+parameters(1).hiding*blind==masks[i]+m.rows[row]*c,"B1 constrained row knowledge/zero-tail equation failed");stats.padded_coordinates+=1024-active;++stats.verified_rows;}rr.end();stats.verify_seconds+=seconds(t);++stats.chunks;
}
Registered Registered::establish(IO&io,const Master&m,const Secret*s,const std::string&role,RegistrationMetrics&stats,const std::string&attack){
 validate(m.spec);need(!role.empty() && role.size()<=40,"B1 registration role");bindPublic(io,"B1/register/"+role+"/master",encodeMaster(m));std::set<std::string>seen;auto root=identity(m);
 for(std::size_t start=0;start<m.spec.rows;start+=chunkRows)checkChunk(io,m,s,start,std::min(chunkRows,m.spec.rows-start),role,stats,seen,root,attack);
 need(stats.verified_rows==m.spec.rows && stats.padded_coordinates==m.spec.N-m.spec.actual,"B1 provisional/incomplete registration");Writer w;w.text(registrationSuite);w.text(identity(m));w.text(io.session());w.number(stats.verified_rows);w.number(stats.chunks);auto parent=io.prefix();w.raw(Bytes(parent.begin(),parent.end()));bindPublic(io,"B1/register/"+role+"/complete",w.b);return Registered(io,m);
}
}
